import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    # erfinv input must be in range (-1, 1)
    x = torch.empty(shape, dtype=dtype, device=device).uniform_(-0.99, 0.99)
    return {"x": x}


def run(x):
    return torch.erfinv(x)
